```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Count Array Occurrences</title>
</head>
<body>
    <script>
        var array = ['1', '2', '2', '3', '4'];
        var valueToFind = '2';

